export { ListGroup, type ListGroupProps } from "./list-group";
export {
	type ListGroupContextValue,
	ListGroupProvider,
	useListGroup,
	useListGroupContext,
} from "./list-group.context";
export type { ListGroupSlotProps, ListGroupTextProps } from "./list-group.types";
export {
	LIST_GROUP_FOREGROUND_TOKEN,
	LIST_GROUP_SIZES,
	LIST_GROUP_SUFFIX_ICON_TOKEN,
	LIST_GROUP_VARIANTS,
	type ListGroupSize,
	type ListGroupVariant,
	type ListGroupVariantProps,
	listGroupVariants,
} from "./list-group.variants";
export type { ListGroupItemProps } from "./list-group-item";
export type { ListGroupIconProps, ListGroupItemSuffixProps } from "./list-group-item-suffix";

import type { ReactElement } from "react";
import { View } from "react-native";
import type { ListGroupSlotProps } from "./list-group.types";
import { listGroupVariants } from "./list-group.variants";

/** The text column of a row, taking whatever width the prefix and suffix leave. */
export function ListGroupItemContent({ className, ...props }: ListGroupSlotProps): ReactElement {
	return <View className={listGroupVariants().content({ className })} {...props} />;
}
ListGroupItemContent.displayName = "DelacourUI.ListGroup.ItemContent";

import type { ReactElement } from "react";
import { Text } from "@registry/ui/text";
import { useListGroupPart } from "./list-group.context";
import type { ListGroupTextProps } from "./list-group.types";
import { listGroupVariants } from "./list-group.variants";

/** The row's secondary line, a step down in scale and on the muted token. */
export function ListGroupItemDescription({ className, ...props }: ListGroupTextProps): ReactElement {
	const { size } = useListGroupPart("ListGroup.ItemDescription");
	return <Text className={listGroupVariants({ size }).description({ className })} {...props} />;
}
ListGroupItemDescription.displayName = "DelacourUI.ListGroup.ItemDescription";

import { type ReactElement, useMemo } from "react";
import { View } from "react-native";
import { IconDefaultsProvider } from "@registry/ui/icon";
import { useListGroupPart } from "./list-group.context";
import type { ListGroupSlotProps } from "./list-group.types";
import { LIST_GROUP_FOREGROUND_TOKEN, listGroupVariants } from "./list-group.variants";

/**
 * The leading slot of a row.
 *
 * Its subtree inherits the list group's icon size and the foreground token, so a
 * bare `<Icon icon={IconWifi} />` comes out right with nothing said at the call
 * site — the same cascade a `Button` gives its icons.
 */
export function ListGroupItemPrefix({ className, children, ...props }: ListGroupSlotProps): ReactElement {
	const { size } = useListGroupPart("ListGroup.ItemPrefix");
	const slots = listGroupVariants({ size });
	const iconClassName = slots.prefixIcon();
	const iconDefaults = useMemo(
		() => ({ className: iconClassName, color: LIST_GROUP_FOREGROUND_TOKEN }),
		[iconClassName]
	);

	return (
		<View className={slots.prefix({ className })} {...props}>
			<IconDefaultsProvider value={iconDefaults}>{children}</IconDefaultsProvider>
		</View>
	);
}
ListGroupItemPrefix.displayName = "DelacourUI.ListGroup.ItemPrefix";

import { Children, type ReactElement } from "react";
import { View } from "react-native";
import { IconChevronRight } from "@registry/icons/central";
import { cn } from "@registry/lib/cn";
import { Icon, type IconSize } from "@registry/ui/icon";
import { useListGroupPart } from "./list-group.context";
import type { ListGroupSlotProps } from "./list-group.types";
import { LIST_GROUP_SUFFIX_ICON_TOKEN, listGroupVariants } from "./list-group.variants";

export type ListGroupIconProps = {
	/** A named size, or an edge length in points. Beats `className`. */
	size?: IconSize | number;
	/** A theme colour token or a literal. Defaults to `muted-foreground`. */
	color?: string;
	/** A `size-*` utility, beating the group's own suffix size. */
	className?: string;
};

export type ListGroupItemSuffixProps = ListGroupSlotProps & {
	/** Tunes the default chevron. Ignored once the suffix has children of its own. */
	iconProps?: ListGroupIconProps;
};

/**
 * The trailing slot of a row, showing a chevron unless given content.
 *
 * The chevron is a hint that the row leads somewhere, so it sits on the muted
 * token and a step below the leading icon rather than competing with either.
 */
export function ListGroupItemSuffix({
	className,
	iconProps,
	children,
	...props
}: ListGroupItemSuffixProps): ReactElement {
	const { size } = useListGroupPart("ListGroup.ItemSuffix");
	const slots = listGroupVariants({ size });
	const hasContent = Children.toArray(children).length > 0;

	return (
		<View className={slots.suffix({ className })} {...props}>
			{hasContent ? (
				children
			) : (
				<Icon
					className={cn(slots.suffixIcon(), iconProps?.className)}
					color={iconProps?.color ?? LIST_GROUP_SUFFIX_ICON_TOKEN}
					icon={IconChevronRight}
					size={iconProps?.size}
				/>
			)}
		</View>
	);
}
ListGroupItemSuffix.displayName = "DelacourUI.ListGroup.ItemSuffix";

import type { ReactElement } from "react";
import { Text } from "@registry/ui/text";
import { useListGroupPart } from "./list-group.context";
import type { ListGroupTextProps } from "./list-group.types";
import { listGroupVariants } from "./list-group.variants";

/**
 * The row's primary line.
 *
 * Carries its own colour and type scale, read from the list group's context: a
 * React Native `View` does not cascade colour to a `Text` descendant.
 */
export function ListGroupItemTitle({ className, ...props }: ListGroupTextProps): ReactElement {
	const { size } = useListGroupPart("ListGroup.ItemTitle");
	return <Text className={listGroupVariants({ size }).title({ className })} {...props} />;
}
ListGroupItemTitle.displayName = "DelacourUI.ListGroup.ItemTitle";

import { Children, type ReactElement, type ReactNode, useMemo } from "react";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { useListGroupPart } from "./list-group.context";
import { listGroupVariants } from "./list-group.variants";
import { ListGroupItemContent } from "./list-group-item-content";
import { ListGroupItemTitle } from "./list-group-item-title";

export type ListGroupItemProps = Omit<PressableProps, "children" | "disabled"> & {
	isDisabled?: boolean;
	children?: ReactNode;
};

/**
 * One row of a list group.
 *
 * Plain string or number children are wrapped in a title inside a content
 * column; pass the compound parts when a row needs a prefix, a description or a
 * suffix. React Native cannot render a string outside a `<Text>`, so the wrap is
 * not a convenience — without it `<ListGroup.Item>Wi-Fi</ListGroup.Item>` would
 * crash.
 *
 * A row is a `Pressable`, so `feedback`, `haptic` and the rest come from there
 * rather than being restated here. Only the default differs: `fade`, because a
 * full-bleed row that scales reads as the whole card flexing rather than as one
 * row responding.
 */
export function ListGroupItem({
	feedback = "fade",
	isDisabled = false,
	className,
	children,
	...props
}: ListGroupItemProps): ReactElement {
	const { size } = useListGroupPart("ListGroup.Item");
	const content = useMemo(() => wrapTextChildren(children), [children]);

	return (
		<Pressable
			className={listGroupVariants({ isDisabled, size }).item({ className })}
			disabled={isDisabled}
			feedback={feedback}
			{...props}
		>
			{content}
		</Pressable>
	);
}
ListGroupItem.displayName = "DelacourUI.ListGroup.Item";

/**
 * Wraps bare text children in a title inside a content column.
 *
 * Consecutive strings and numbers are collected into a single title rather than
 * one each — `Row {index}` is one piece of text, and wrapping the parts
 * separately would space them apart by the row's gap.
 *
 * Lives here rather than with the root: it is the row that wraps its own text,
 * and importing it from `./list-group` would close a cycle back through the
 * root. See AGENTS.md rule 3.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(
			<ListGroupItemContent key={`content-${output.length}`}>
				<ListGroupItemTitle>{run.join("")}</ListGroupItemTitle>
			</ListGroupItemContent>
		);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { ListGroupSize, ListGroupVariant } from "./list-group.variants";

export type ListGroupContextValue = {
	/** Size of the list group. */
	size: ListGroupSize;
	/** Visual variant of the list group. */
	variant: ListGroupVariant;
};

const ListGroupContext = createContext<ListGroupContextValue | null>(null);

/**
 * Supplies the enclosing list group's size and variant to its subtree.
 *
 * Lives in its own module, importing nothing but `list-group.variants`, so a
 * component the list group renders can read it without importing `../list-group`
 * and closing a cycle through `list-group.tsx`. See AGENTS.md rule 3.
 */
export function ListGroupProvider({
	value,
	children,
}: {
	value: ListGroupContextValue;
	children: ReactNode;
}): ReactElement {
	return <ListGroupContext value={value}>{children}</ListGroupContext>;
}
ListGroupProvider.displayName = "DelacourUI.ListGroup.Provider";

/** The enclosing list group's context, or null outside a `<ListGroup>`. */
export function useListGroupContext(): ListGroupContextValue | null {
	return use(ListGroupContext);
}

/**
 * Reads the enclosing list group's size and variant.
 *
 * Lets a custom row style itself to match without the list group having to pass
 * props down through every slot. Throws outside a `<ListGroup>` — use
 * {@link useListGroupContext} where the enclosing list group is optional.
 */
export function useListGroup(): ListGroupContextValue {
	const context = useListGroupContext();
	if (!context) {
		throw new Error("useListGroup must be called inside a <ListGroup>.");
	}
	return context;
}

/**
 * The enclosing list group's context, for a compound part that cannot work
 * without one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useListGroup}, whose error message names the hook rather
 * than a part.
 */
export function useListGroupPart(component: string): ListGroupContextValue {
	const context = useListGroupContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <ListGroup>.`);
	}
	return context;
}

import { Children, isValidElement, type ReactElement, type ReactNode, useMemo } from "react";
import { View, type ViewProps } from "react-native";
import { Separator } from "@registry/ui/separator";
import { type ListGroupContextValue, ListGroupProvider } from "./list-group.context";
import { type ListGroupSize, type ListGroupVariant, listGroupVariants } from "./list-group.variants";
import { ListGroupItem } from "./list-group-item";
import { ListGroupItemContent } from "./list-group-item-content";
import { ListGroupItemDescription } from "./list-group-item-description";
import { ListGroupItemPrefix } from "./list-group-item-prefix";
import { ListGroupItemSuffix } from "./list-group-item-suffix";
import { ListGroupItemTitle } from "./list-group-item-title";

export type ListGroupProps = ViewProps & {
	variant?: ListGroupVariant;
	size?: ListGroupSize;
	/** Draw a divider between adjacent children. On by default. */
	isDivided?: boolean;
	className?: string;
	children?: ReactNode;
};

function ListGroupRoot({
	variant = "default",
	size = "md",
	isDivided = true,
	className,
	children,
	...props
}: ListGroupProps): ReactElement {
	const context = useMemo<ListGroupContextValue>(() => ({ size, variant }), [size, variant]);

	const slots = listGroupVariants({ size, variant });
	const dividerClassName = slots.divider();

	const content = useMemo(
		() => (isDivided ? withDividers(children, dividerClassName) : children),
		[children, isDivided, dividerClassName]
	);

	return (
		<ListGroupProvider value={context}>
			<View className={slots.root({ className })} {...props}>
				{content}
			</View>
		</ListGroupProvider>
	);
}

/**
 * Inserts a divider between adjacent children.
 *
 * A pair is skipped when either side already is a `Separator`, so a hand-placed
 * divider is never doubled. `Children.toArray` drops the nulls and booleans a
 * conditional child leaves behind, so a row rendered only some of the time does
 * not strand a divider where nothing follows it.
 */
function withDividers(children: ReactNode, dividerClassName: string): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];

	for (const [index, child] of items.entries()) {
		if (index > 0 && !isSeparator(items[index - 1]) && !isSeparator(child)) {
			output.push(<Separator className={dividerClassName} key={`divider-${index}`} />);
		}
		output.push(child);
	}

	return output;
}

function isSeparator(node: ReactNode): boolean {
	return isValidElement(node) && node.type === Separator;
}

/**
 * A surface grouping related rows under one rounded, clipped container.
 *
 * `size` and `variant` reach the sub-components through context, so a row's
 * title picks its own text colour and type scale. That indirection is not
 * incidental: a React Native `View` does not cascade colour to a `Text`
 * descendant the way a DOM element would.
 *
 * Dividers are inserted between adjacent children rather than written out at
 * every call site, inset to line up with the rows' own padding. A `Separator`
 * placed by hand is respected — no divider is added on either side of it — so a
 * caller can still control one gap without turning the whole feature off.
 *
 * @example
 * <ListGroup>
 *   <ListGroup.Item onPress={openProfile}>
 *     <ListGroup.ItemPrefix>
 *       <Icon icon={IconUser} />
 *     </ListGroup.ItemPrefix>
 *     <ListGroup.ItemContent>
 *       <ListGroup.ItemTitle>Personal info</ListGroup.ItemTitle>
 *       <ListGroup.ItemDescription>Name, email, phone</ListGroup.ItemDescription>
 *     </ListGroup.ItemContent>
 *     <ListGroup.ItemSuffix />
 *   </ListGroup.Item>
 * </ListGroup>
 */
export const ListGroup = Object.assign(ListGroupRoot, {
	/** One row of a list group. Bare text children are wrapped in a title inside a content column. */
	Item: ListGroupItem,
	/** The leading slot of a row. Its subtree inherits the group's icon size and foreground token. */
	ItemPrefix: ListGroupItemPrefix,
	/** The text column of a row, taking whatever width the prefix and suffix leave. */
	ItemContent: ListGroupItemContent,
	/** The row's primary line. Carries its own colour — a `View` cannot cascade one to a `Text`. */
	ItemTitle: ListGroupItemTitle,
	/** The row's secondary line, a step down in scale and on the muted token. */
	ItemDescription: ListGroupItemDescription,
	/** The trailing slot of a row, showing a chevron unless given content. */
	ItemSuffix: ListGroupItemSuffix,
	displayName: "DelacourUI.ListGroup",
});

import type { ReactNode } from "react";
import type { TextProps, ViewProps } from "react-native";

/**
 * The shape of a row's leading, text and trailing slots.
 *
 * Shared by `ListGroup.ItemPrefix` and `ListGroup.ItemContent`, and extended by
 * `ListGroup.ItemSuffix`, so it lives in a leaf rather than in one of them
 * arbitrarily.
 */
export type ListGroupSlotProps = ViewProps & { className?: string; children?: ReactNode };

/** The shape of a row's two text lines, `ItemTitle` and `ItemDescription`. */
export type ListGroupTextProps = TextProps & { className?: string };

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";

export const LIST_GROUP_VARIANTS = ["default", "secondary", "tertiary", "transparent"] as const;

export const LIST_GROUP_SIZES = ["sm", "md", "lg"] as const;

export type ListGroupVariant = (typeof LIST_GROUP_VARIANTS)[number];
export type ListGroupSize = (typeof LIST_GROUP_SIZES)[number];

/** Theme token an icon in `ListGroup.ItemPrefix` inherits. */
export const LIST_GROUP_FOREGROUND_TOKEN = "foreground";

/** Theme token the default trailing chevron inherits. */
export const LIST_GROUP_SUFFIX_ICON_TOKEN = "muted-foreground";

/**
 * Styling for every part of a list group.
 *
 * Both icon slots name a step on the shared `--spacing-icon-*` scale, the same
 * one `Icon` and `Spinner` use, so a row's glyph lines up with every other glyph
 * in the library rather than carrying a private number.
 *
 * One slotted `tv()` rather than a call per part, because size is not
 * decoration here: it drives the row metrics, the title and description type
 * scale, both icon sizes *and* the divider inset. Those five belong on one axis
 * rather than in five places that can drift apart — the divider inset tracking
 * the row's padding is asserted as a pair in the tests for exactly that reason.
 *
 * `overflow-hidden` on the root is load-bearing rather than tidiness: a pressed
 * row fades to the edge of its own box, and the first and last rows would square
 * off the group's corners without it.
 *
 * The root and item slots hold no `text-*` utility — a React Native `View` does
 * not cascade colour to a `Text` descendant, so the text tokens live on the
 * title and description slots.
 *
 * `w-full` on the item matters because the root clips: without it a short row
 * leaves the press feedback ending mid-card instead of spanning it.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const listGroupVariants = tv({
	slots: {
		root: "overflow-hidden border border-transparent",
		item: "w-full flex-row items-center",
		/** Positioning only for a divider the root inserts — the line is a `Separator`. */
		divider: "",
		prefix: "items-center justify-center",
		/** Edge length an `Icon` in the prefix inherits. */
		prefixIcon: "",
		content: "flex-1 justify-center gap-0.5",
		title: "font-medium text-foreground",
		description: "text-muted-foreground",
		suffix: "items-center justify-center",
		/** Edge length of the default trailing chevron. */
		suffixIcon: "",
	},
	variants: {
		variant: {
			default: { root: "border-border bg-card" },
			secondary: { root: "bg-secondary" },
			tertiary: { root: "bg-tertiary" },
			transparent: { root: "bg-transparent" },
		},
		size: {
			sm: {
				root: "rounded-xl",
				item: "min-h-12 gap-2.5 px-3 py-2",
				divider: "mx-3",
				prefixIcon: "size-icon-md",
				suffixIcon: "size-icon-xs",
				title: "text-sm",
				description: "text-xs",
			},
			md: {
				root: "rounded-2xl",
				item: "min-h-14 gap-3 px-4 py-3",
				divider: "mx-4",
				prefixIcon: "size-icon-lg",
				suffixIcon: "size-icon-sm",
				title: "text-base",
				description: "text-sm",
			},
			lg: {
				root: "rounded-2xl",
				item: "min-h-16 gap-3.5 px-5 py-4",
				divider: "mx-5",
				prefixIcon: "size-icon-xl",
				suffixIcon: "size-icon-md",
				title: "text-lg",
				description: "text-base",
			},
		},
		// The empty `false` branch types the prop as `boolean` rather than `true`.
		// See the note in button.variants.ts.
		isDisabled: { true: { item: "opacity-50" }, false: {} },
	},
	defaultVariants: {
		variant: "default",
		size: "md",
		isDisabled: false,
	},
});

export type ListGroupVariantProps = VariantProps<typeof listGroupVariants>;
